# Implementasi Simulator DAG Scheduler: Pemecahan Stage Boundary Berbasis Dependensi
class DAGSchedulerSimulator:
    def __init__(self):
        self.stages = []

    def build_stages(self, transformation_chain):
        current_stage = {'stage_id': 0, 'operations': [], 'type': 'NARROW'}
        stage_counter = 0

        for op_name, dep_type in transformation_chain:
            if dep_type == 'WIDE':
                # Batas Stage: Wide dependency memicu Shuffle barrier baru!
                current_stage['operations'].append(op_name)
                self.stages.append(current_stage)
                stage_counter += 1
                current_stage = {'stage_id': stage_counter, 'operations': [], 'type': 'SHUFFLE_RECEIVER'}
            else:
                current_stage['operations'].append(op_name)

        self.stages.append(current_stage)
        return self.stages

# Rantai operasi: textFile -> map -> filter -> reduceByKey (WIDE) -> map -> count
pipeline_ops = [
    ('textFile', 'NARROW'),
    ('map(parse)', 'NARROW'),
    ('filter(valid)', 'NARROW'),
    ('reduceByKey(sum)', 'WIDE'),   # Stage Boundary!
    ('map(format)', 'NARROW'),
    ('sortBy(val)', 'WIDE')         # Stage Boundary!
]

scheduler = DAGSchedulerSimulator()
stages = scheduler.build_stages(pipeline_ops)

print(f'Dekomposisi Graf DAG Spark ({len(pipeline_ops)} Operasi):')
for s in stages:
    print(f'  [Stage {s["stage_id"]}] Tipe: {s["type"]:16s} | Operasi Pipelined: {s["operations"]}')
print('Kesimpulan: DAGScheduler memotong stage persis pada operasi shuffle wide dependency.')

# Implementasi Model Mini DataFrame: Skema Terstruktur, Tipe Data, & Proyeksi Kolom
class StructField:
    def __init__(self, name, data_type):
        self.name = name
        self.data_type = data_type

class MiniDataFrame:
    def __init__(self, records, schema):
        self.schema = {f.name: f.data_type for f in schema}
        self.records = records
        self._validate_records()

    def _validate_records(self):
        for r in self.records:
            for col, expected_type in self.schema.items():
                if col in r and not isinstance(r[col], expected_type):
                    raise TypeError(f'Kolom {col} mengharuskan {expected_type}, diterima {type(r[col])}')

    def select(self, *cols):
        new_schema = [StructField(c, self.schema[c]) for c in cols]
        projected = [{c: r[c] for c in cols} for r in self.records]
        return MiniDataFrame(projected, new_schema)

    def filter(self, condition_fn):
        new_schema = [StructField(c, t) for c, t in self.schema.items()]
        filtered = [r for r in self.records if condition_fn(r)]
        return MiniDataFrame(filtered, new_schema)

schema_def = [
    StructField('user_id', int),
    StructField('tier', str),
    StructField('score', float)
]
raw_rows = [
    {'user_id': 101, 'tier': 'GOLD', 'score': 92.5},
    {'user_id': 102, 'tier': 'SILVER', 'score': 74.0},
    {'user_id': 103, 'tier': 'GOLD', 'score': 88.0}
]

df = MiniDataFrame(raw_rows, schema_def)
filtered_df = df.filter(lambda r: r['tier'] == 'GOLD').select('user_id', 'score')

print(f'Struktur Skema DataFrame: {df.schema}')
print(f'Hasil Transformasi DataFrame (Filter GOLD & Proyeksi):')
for r in filtered_df.records:
    print(f'  - Record: {r}')
print('Kesimpulan: DataFrame mengikat data dengan skema kuat untuk optimasi relasional.')

