import numpy as np

# Implementasi Simulasi Operasi Relasional PySpark: Select, Filter, WithColumn, & GroupBy Agg
class PySparkEngineSimulator:
    def __init__(self, data_rows):
        self.data = data_rows

    def with_column(self, new_col_name, transform_fn):
        for r in self.data:
            r[new_col_name] = transform_fn(r)
        return self

    def filter(self, predicate_fn):
        self.data = [r for r in self.data if predicate_fn(r)]
        return self

    def group_by_agg(self, group_col, agg_col):
        # Two-phase aggregation simulation
        groups = {}
        for r in self.data:
            k = r[group_col]
            val = r[agg_col]
            if k not in groups:
                groups[k] = {'sum': 0.0, 'count': 0}
            groups[k]['sum'] += val
            groups[k]['count'] += 1

        # Compute global average
        results = []
        for k, stats in sorted(groups.items()):
            results.append({
                group_col: k,
                'total_amount': stats['sum'],
                'avg_amount': stats['sum'] / stats['count'],
                'tx_count': stats['count']
            })
        return results

raw_transactions = [
    {'tx_id': 1, 'category': 'Elektronik', 'price': 500.0, 'discount': 0.1},
    {'tx_id': 2, 'category': 'Fashion', 'price': 100.0, 'discount': 0.2},
    {'tx_id': 3, 'category': 'Elektronik', 'price': 800.0, 'discount': 0.05},
    {'tx_id': 4, 'category': 'Buku', 'price': 40.0, 'discount': 0.0},
    {'tx_id': 5, 'category': 'Fashion', 'price': 250.0, 'discount': 0.15}
]

engine = PySparkEngineSimulator(raw_transactions)
# Pipeline: withColumn(net_amount) -> filter(price > 50) -> groupBy(category).agg(sum, avg)
summary = engine \
    .with_column('net_amount', lambda r: r['price'] * (1 - r['discount'])) \
    .filter(lambda r: r['price'] > 50.0) \
    .group_by_agg('category', 'net_amount')

print('Hasil Eksekusi Relasional PySpark Pipeline:')
for s in summary:
    print(f'  - Kategori {s["category"]:11s}: Total Net=${s["total_amount"]:6.2f} | Rata-rata=${s["avg_amount"]:6.2f} | N={s["tx_count"]}')
print('Kesimpulan: Two-phase aggregation meminimalkan footprint pertukaran data lintas partisi.')
